async function api(path,body){let r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'X-Neural-Token':window.NEURAL_TOKEN,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let v=await r.json();if(!r.ok||v.error)throw Error(v.error||'Request failed');return v}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function fail(e){$('#error').hidden=false;$('#error').textContent=e.message||e}
function download(v,name){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(v,null,2)],{type:'application/json'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function bind(id,fn){let el=$('#'+id);if(el)el.onclick=async()=>{el.disabled=true;try{await fn()}catch(e){fail(e)}finally{el.disabled=false}}}
async function attachElementThinking(v){const epoch=thinkingEpoch;if(!intelligenceOrder.includes(v)||v==='studymonitor'||v==='moduleflow'||v==='thoughtcloud')return;const host=document.createElement('div');host.id='elementThinkingHost';$('#content').before(host);const m=await import('/assets/element_thinking.js');if(epoch!==thinkingEpoch){host.remove();return;}const dispose=await m.mountElementThinking(host,api,v);if(epoch!==thinkingEpoch){dispose();host.remove();return;}thinkingDispose=()=>{dispose();host.remove();};}
function navigate(v){thinkingEpoch++;if(thinkingDispose){thinkingDispose();thinkingDispose=null;}document.getElementById('elementThinkingHost')?.remove();if(academyDispose){academyDispose();academyDispose=null}view=v;const engineMenu=document.getElementById('engineNavigation');if(engineMenu)engineMenu.value=[...engineMenu.options].some(option=>option.value===v)?v:'';document.body.dataset.view=v;document.dispatchEvent(new CustomEvent('neural-view-change',{detail:{view:v}}));location.hash=v;$('#error').hidden=true;currentReceipt=null;$('#nav').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));let d=(v==='thinkingmindspace'?['Thinking mind space','Live observation processing, checked work and reusable native workflows.']:descriptions[v])||[state?.sections[v]||v,'Built-in calculations using the shared data path and learner.'];$('#title').textContent=d[0];$('#subtitle').textContent=d[1];$('#eyebrow').textContent=['home','pipeline','classifier','field'].includes(v)?'SHARED INTELLIGENCE':'NEURAL APP / '+v.replaceAll('_',' ').toUpperCase();render().then(()=>{if(view===v)return attachElementThinking(v);}).catch(fail)}
