$('#nav').innerHTML=navigationLayout.lessons.map(([g,items])=>'<label>'+g+'</label>'+items.map(([id,name])=>`<button data-view="${id}" style="${id==='talkwork'?'border:2px solid #86b1cb;background:#244b65;color:#eef8ff;font-weight:800;margin-bottom:12px':''}">${name}</button>`).join('')).join('');$('#nav').onclick=e=>{let b=e.target.closest('button');if(b)navigate(b.dataset.view)};bind('save',async()=>{await api('checkpoint',{});toast('Shared checkpoint saved')});
const stats=()=>`<div class="stats"><div class="stat"><span class="kicker">Neural updates</span><strong id="statUpdates">${state?.network.updates||0}</strong><small>Synthetic classifier</small></div><div class="stat"><span class="kicker">Engine learning</span><strong id="statLearn">${state?.learning.updates||0}</strong><small>Recorded result reconstruction</small></div><div class="stat"><span class="kicker">Reviewed feedback</span><strong id="statReviewed">${state?.learning.reviewed_updates||0}</strong><small>Explicit preference labels</small></div><div class="stat"><span class="kicker">Runtime memory</span><strong id="statMemory">${state?.metrics.rss_mb??'—'} <small>MB</small></strong><small>Python engine process</small></div></div>`;
const visual=()=>'<div class="panel hero"><img id="sceneImage" alt="Live procedural neural scene"><div class="caption"><strong>A shared field of possibilities.</strong><small>NASA solar and Earth imagery. A volumetric hydrogen study. Live field bits drive the connecting data pulses.</small></div><div class="scenecontrols"><select id="sceneSelect">'+['Cosmos','Hydrogen','Stellar','Dyson','Earth','Biosphere','Matrix'].map(x=>`<option ${x===scene?'selected':''}>${x}</option>`).join('')+'</select></div></div>';
const resultBox=()=>'<div class="panel pad"><div class="resulthead"><h2>Actual engine result</h2><span id="resultStatus" class="kicker">Waiting for input</span></div><div id="resultVisual"></div><pre id="resultOutput">Run this section to inspect a result.</pre><div class="actions" id="resultActions" hidden><button id="exportResult">Export result</button><button id="reviewGood">Useful · train from feedback</button><button id="reviewBad">Not useful · train from feedback</button></div></div>';
function result(value,receipt){currentReceipt=receipt;$('#resultStatus').textContent=receipt?'RECEIPT #'+receipt:'COMPLETE';let text=JSON.stringify(value,null,2);$('#resultOutput').textContent=text.length>90000?text.slice(0,90000)+'\n… Full result is available through Export result.':text;$('#resultActions').hidden=!receipt;bind('exportResult',async()=>download(await api('receipts?id='+receipt),'neural-result-'+receipt+'.json'));for(const [id,target] of [['reviewGood',1],['reviewBad',0]])bind(id,async()=>{let r=await api('feedback',{receipt,target,note:'Reviewed from the integrated app interface'});toast('Feedback learned · '+r.supervised_updates+' reviewed updates');$('#reviewGood').disabled=$('#reviewBad').disabled=true});if(value.qutrits){$('#resultVisual').innerHTML='<p class="ok">Round trip: '+(value.round_trip?'verified':'failed')+'</p><div class="qutritstrip">'+value.qutrits.slice(0,32).map(q=>'<b>|F'+q.trit+'⟩</b>').join('')+'</div><p>Uniform basis probabilities; ternary identity is carried by phase.</p>'}}
async function run(section,input){$('#resultStatus').textContent='QUEUED';const job=await api('run',{section,input});let current=view;for(;;){await new Promise(r=>setTimeout(r,250));let j=await api('job?id='+job.id);if(view!==current)return;if(j.status==='error')throw Error(j.error);$('#resultStatus').textContent=j.status.toUpperCase();if(j.status==='complete'){result(j.result,j.receipt);await refresh();return j}}}
