async function renderEngine(){let section=view;let extra='';if(section==='translation')extra='<label class="field">Binary digits (optional)<textarea id="bits" placeholder="00010110 — spaces and underscores allowed"></textarea></label>';
if(section==='signals')extra='<div class="formgrid"><label class="field">Generator<select id="mode">'+['Seeded test','OS random','Counter','Cellular automaton'].map(x=>'<option>'+x+'</option>').join('')+'</select></label><label class="field">Bytes<input id="size" type="number" min="1" max="1024" value="64"></label></div><label class="field">Seed<input id="seed" value="neural-app"></label>';
if(section==='profiles')extra='<label class="field">Five target weights (0 to 1)<input id="targets" value="0.9, 0.95, 0.85, 0.9, 0.95"></label><div class="actions"><button id="elevator">Run sky-elevator model</button></div>';
if(section==='scenario')extra='<div class="formgrid">'+['access','comfort','transition','automation'].map(x=>`<label class="field">${x}<input id="scenario-${x}" type="number" min="0" max="100" value="50"></label>`).join('')+'</div><label class="toggle"><input id="valve" type="checkbox" checked>Resource valve</label><label class="toggle"><input id="gate" type="checkbox" checked>Automation gate</label>';
if(section==='reference'){referenceData=referenceData||await api('reference');extra='<label class="field">Choose a built-in reference engine<select id="referenceEngine">'+Object.entries(referenceData.families).map(([name,rows])=>`<optgroup label="${esc(name)}">${rows.map(r=>'<option>'+esc(r)+'</option>').join('')}</optgroup>`).join('')+'</select></label><p>Editable example inputs are software scenarios. They do not trigger real financial or infrastructure operations.</p>'}
$('#content').innerHTML='<div class="grid"><section class="panel pad"><h2>'+esc(state.sections[section]||section)+'</h2>'+(['signals','profiles','scenario'].includes(section)?'':commonInput())+extra+'<details><summary>Advanced structured engine inputs</summary><textarea id="options" class="mono">{}</textarea></details><div class="actions"><button class="primary" id="runEngine">Run built-in section ↗</button></div><p>Runs directly inside the shared app runtime. Results use the same checked binary / ternary / qutrit transport as the pipeline.</p></section>'+resultBox()+'</div>';
if(section==='reference'){let update=()=>{$('#options').value=JSON.stringify({reference_engines:{[$('#referenceEngine').value]:referenceData.examples[$('#referenceEngine').value]}},null,2)};$('#referenceEngine').onchange=update;update()}
bind('runEngine',()=>{let input={text:$('#engineText')?.value||'',options:JSON.parse($('#options').value)};if(section==='translation')input.bits=$('#bits').value||undefined;if(section==='signals')Object.assign(input,{mode:$('#mode').value,size:Number($('#size').value),seed:$('#seed').value});if(section==='profiles')Object.assign(input,{targets:$('#targets').value.split(',').map(Number),steps:100});if(section==='scenario')input.scenario=Object.fromEntries([...['access','comfort','transition','automation'].map(x=>[x,Number($('#scenario-'+x).value)]),['valve',$('#valve').checked],['gate',$('#gate').checked]]);return run(section,input)});bind('elevator',()=>run('profiles',{action:'elevator'}))}
async function setupScene(){let el=$('#sceneSelect');if(el)el.onchange=()=>{scene=el.value;loadScene()};await loadScene()}
async function loadScene(){if(sceneBusy||document.hidden||!$('#sceneImage'))return;sceneBusy=true;let selected=scene;try{let r=await fetch('/api/scene?preset='+encodeURIComponent(selected),{headers:{'X-Neural-Token':window.NEURAL_TOKEN}});if(!r.ok)throw Error((await r.json()).error);let u=URL.createObjectURL(await r.blob());if($('#sceneImage'))$('#sceneImage').src=u;else URL.revokeObjectURL(u);if(sceneURL)URL.revokeObjectURL(sceneURL);sceneURL=u}catch(e){if($('#sceneImage'))$('#sceneImage').alt=e.message}finally{sceneBusy=false}}
function canvas(id){let c=$('#'+id);if(!c)return null;let d=window.devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;c.width=w*d;c.height=h*d;let ctx=c.getContext('2d');ctx.scale(d,d);ctx.fillStyle='#09121d';ctx.fillRect(0,0,w,h);return {ctx,w,h}}
function draw(){if(!state||document.hidden)return;let field=canvas('fieldCanvas');if(field){let {ctx,w,h}=field,vs=state.field.values;let pts=vs.map((v,i)=>{let a=i/96*Math.PI*2,r=Math.min(w,h)*(.31+.045*v);return [w/2+Math.cos(a)*r,h/2+Math.sin(a)*r]});pts.forEach(([x,y],i)=>{let [a,b]=pts[(i+11)%96];ctx.strokeStyle='rgba(94,189,202,'+(.04+Math.abs(vs[i])*.12)+')';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(a,b);ctx.stroke();ctx.fillStyle=vs[i]>0?'#6ce5c2':'#6999df';ctx.beginPath();ctx.arc(x,y,2+Math.abs(vs[i])*2,0,7);ctx.fill()});ctx.fillStyle='#a8c8d8';ctx.font='12px Consolas';ctx.textAlign='center';ctx.fillText(state.field.ticks+' ticks',w/2,h/2);ctx.font='10px Consolas';ctx.fillText('96 SHARED RECURRENT NODES',w/2,h/2+20)}let net=canvas('networkCanvas');if(net){let {ctx,w,h}=net,g=state.network.grid;if(g){let cell=Math.min(w/21,h/21),left=(w-21*cell)/2;g.forEach((row,y)=>row.forEach((v,x)=>{ctx.fillStyle=`rgb(${Math.round(30+v*70)},${Math.round(75+v*145)},${Math.round(160-v*25)})`;ctx.fillRect(left+x*cell,y*cell,cell+.5,cell+.5)}))}let m=$('#networkMetrics');if(m)m.textContent='Held-out loss '+state.network.loss.toFixed(4)+' · accuracy '+(state.network.accuracy*100).toFixed(1)+'% · '+state.network.updates+' weight updates'}}
async function refresh(){if(pollBusy||document.hidden)return;pollBusy=true;try{state=await api('state?visuals='+(['home','field','classifier'].includes(view)?'1':'0'));updateProcessStrip();document.dispatchEvent(new CustomEvent('neural-runtime-snapshot',{detail:state}));$('#connection').textContent='Shared runtime connected';$('#resources').textContent=(state.metrics.rss_mb??'—')+' MB engine · '+state.metrics.threads+' threads · '+(state.metrics.child_processes??'—')+' child processes';$('#queue').textContent=state.queue+' queued';$('#learnCount').textContent=state.learning.updates+' learning steps';if($('#statUpdates'))$('#statUpdates').textContent=state.network.updates;if($('#statLearn'))$('#statLearn').textContent=state.learning.updates;if($('#statReviewed'))$('#statReviewed').textContent=state.learning.reviewed_updates;if($('#statMemory'))$('#statMemory').innerHTML=esc(state.metrics.rss_mb??'—')+' <small>MB</small>';draw()}catch(e){$('#connection').textContent='Connection interrupted';fail(e)}finally{pollBusy=false}}
const providers={llama:'Llama 3',qwen:'Qwen',gemma:'Gemma',gemini:'Gemini',chatgpt:'ChatGPT'};
async function renderChat(){let settings=await api('chat/settings');let config=settings[chatProvider];$('#content').innerHTML='<div class="grid"><section class="panel pad"><h2>Conversation connection</h2><label class="field">Provider<select id="chatProvider">'+Object.entries(providers).map(([id,name])=>`<option value="${id}" ${chatProvider===id?'selected':''}>${name}</option>`).join('')+'</select></label><label class="field">Model<input id="chatModel" value="'+esc(config.model)+'"></label>'+(['llama','qwen','gemma'].includes(chatProvider)?'<label class="field">Local Ollama address<input id="chatEndpoint" value="'+esc(config.endpoint)+'"></label>':'<label class="field">API key<input type="password" id="chatKey" autocomplete="off" placeholder="Leave blank to keep the saved key"></label>')+'<button id="saveChat">Save connection</button><label class="toggle"><input type="checkbox" id="chatRead">Read shared app results for this turn</label><p>Cloud providers receive shared state only when reading is enabled for the turn. Local models use the existing Ollama installation, with bounded context and short idle retention.</p><div class="actions"><button id="chatNew">New conversation</button><button id="chatExport">Export history</button></div><label class="field">Search saved conversations<input id="chatSearch" type="search"></label><div id="chatThreads"></div></section><section class="panel"><div class="panelhead"><h2>'+providers[chatProvider]+'</h2><span id="chatStatus" class="kicker">SAVED HISTORY</span></div><div class="chatlog" id="chatLog"><button id="olderChat" hidden>Load older messages</button><div id="chatMessages"></div><div id="chatPartial"></div></div><div class="pad"><label class="field">Message<textarea id="chatInput" placeholder="Ask about the system or a measured engine result…"></textarea></label><div class="actions"><button id="sendChat" class="primary">Send ↗</button><button id="stopChat" hidden>Stop reply</button></div></div></section></div>';$('#chatProvider').onchange=()=>{if(chatJob){toast('Stop or wait for the current reply first');$('#chatProvider').value=chatProvider;return}chatProvider=$('#chatProvider').value;chatThread=null;renderChat().catch(fail)};bind('saveChat',async()=>{await api('chat/settings',{provider:chatProvider,model:$('#chatModel').value,endpoint:$('#chatEndpoint')?.value||config.endpoint,key:$('#chatKey')?.value});toast('Provider connection saved')});bind('chatNew',async()=>{chatThread=(await api('chat/new',{provider:chatProvider})).id;await loadChat()});bind('chatExport',async()=>{if(!chatThread)throw Error('Choose a conversation first');download(await api('chat/export?thread='+chatThread),'neural-conversation.json')});bind('sendChat',sendChat);bind('stopChat',async()=>{if(chatJob)await api('chat/cancel',{id:chatJob})});bind('olderChat',()=>loadChat(true));let timer;$('#chatSearch').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>chatThreads().catch(fail),250)};await chatThreads();if(chatThread)await loadChat();if(chatJob)watchChat(chatJob)}
async function chatThreads(){let rows=(await api('chat/threads?provider='+chatProvider+'&search='+encodeURIComponent($('#chatSearch').value))).items;$('#chatThreads').innerHTML=rows.map(t=>`<div class="actions"><button data-thread="${t.id}">${esc(t.title)}</button></div>`).join('');document.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>{if(chatJob){toast('Stop or wait for the current reply first');return}chatThread=b.dataset.thread;loadChat().catch(fail)});if(!chatThread&&rows.length)chatThread=rows[0].id;if(chatThread)await loadChat()}
async function loadChat(older=false){if(!chatThread)return;let r=await api('chat/history?thread='+chatThread+(older?'&before='+chatBefore:''));if(r.items.length)chatBefore=r.items[0].id;let markup=r.items.map(m=>`<article class="message ${esc(m.role)}"><small>${m.role==='user'?'You':esc(providers[chatProvider])} · ${esc(new Date(m.stamp*1000).toLocaleString())}</small>${esc(m.content)}</article>`).join('');if(older)$('#chatMessages').insertAdjacentHTML('afterbegin',markup);else $('#chatMessages').innerHTML=markup;$('#olderChat').hidden=!r.more;if(!older)$('#chatLog').scrollTop=$('#chatLog').scrollHeight}
async function sendChat(){if(chatJob)throw Error('A reply is already in progress');let text=$('#chatInput').value.trim();if(!text)throw Error('Enter a message');if(!chatThread)chatThread=(await api('chat/new',{provider:chatProvider})).id;let j=await api('chat/send',{thread:chatThread,text,nexus:$('#chatRead').checked,write:false,desktop:false});chatJob=j.id;$('#chatInput').value='';$('#stopChat').hidden=false;await loadChat();watchChat(j.id)}
async function watchChat(id){clearTimeout(chatTimer);try{let j=await api('chat/job?id='+id);if(view!=='chat'){if(j.status==='running')chatTimer=setTimeout(()=>watchChat(id),1000);else chatJob=null;return}$('#chatStatus').textContent=j.status.toUpperCase();$('#chatPartial').textContent=j.partial||'';if(j.status==='running'){chatTimer=setTimeout(()=>watchChat(id),500);return}chatJob=null;$('#stopChat').hidden=true;$('#chatPartial').textContent='';await loadChat();if(j.error)fail(Error(j.error))}catch(e){chatJob=null;fail(e)}}
