function updateProcessStrip(){const r=state.research||{},topics=Object.values(r.topics||{}),errors=topics.filter(t=>t.processing==='error').length;$('#processLive').textContent=(r.enabled?'Research intake enabled':'Research intake paused')+' · '+(r.pending?'processing '+r.pending.topic:'waiting for next source cycle')+' · '+errors+' source errors';$('#processSource').textContent=topics.length+' topics checked / '+Object.keys(r.queries||{}).length+' configured';$('#processQueue').textContent=state.queue+' queued · '+state.learning.updates+' learned updates';const latest=state.latest[view]||state.latest.pipeline;$('#processOutput').textContent=latest?'Latest '+(state.latest[view]?view:'shared pipeline')+' receipt '+latest.receipt:'No matching receipt observed';}

